/**
 * Race Day Spectator Guide — all content for /guide/race-day lives in this one file.
 * Hand-authored (NOT generated by scripts/convert_xlsx.py), so edit it directly.
 *
 * How to edit:
 * - Anything still unknown is set to `TBD`. It shows on the page as a dashed orange
 *   "TBD — to be confirmed" chip. Search this file for `TBD` to find every open item.
 * - Wrap text in **double asterisks** to make it bold on the page (used for train lines).
 * - Times are plain strings like "10:58 AM". "Be in place by" is computed automatically
 *   as 15 minutes before each stop's `eta`, so change only the `eta`.
 * - Bump `UPDATED` whenever you change something, so viewers know they have the latest.
 *
 * Photos: drop image files into `public/spectator/` and set the matching `src`, e.g.
 *   src: "/spectator/stop1-street.jpg"
 * A `src` of null shows a dashed "Photo coming" box. Slots:
 *   tracking.steps[].image           — app-store.jpg, app-tracking.jpg (done)
 *   outfit.photo                    — full-length photo in the race outfit
 *   stops[].images                   — one course map per stop: stop1/2/3-map.jpg (done)
 */

/** Sentinel for "not known yet" — renders as a visible placeholder chip. */
export const TBD = "TBD";

export const UPDATED = "Oct 25, 2026";

export interface SpectatorImage {
  label: string;
  src: string | null;
}

export interface SpectatorStop {
  name: string;
  area: string;
  /** Short name for the at-a-glance table and the mile table. */
  short: string;
  mile: number;
  eta: string;
  side: string;
  station: string;
  /** Google Maps search text for the exact spot. */
  mapsQuery: string;
  notes: string[];
  images: SpectatorImage[];
  next: string;
  optional?: boolean;
  optionalNote?: string;
}

